import sys
import json
import time
import numpy as np

def compute_cost(perm, A, B):
    n = len(perm)
    cost = 0
    for i in range(n):
        for j in range(n):
            cost += A[i][j] * B[perm[i]][perm[j]]
    return cost

def main():
    start_time = time.time()
    if len(sys.argv) < 3:
        return
    instance_path = sys.argv[1]
    budget = float(sys.argv[2]) if len(sys.argv) >= 3 else float(os.getenv('QAP_TIME_LIMIT_S', '10.0'))
    with open(instance_path) as f:
        data = json.load(f)
    n = data['n']
    A = np.array(data['A'], dtype=np.int64)
    B = np.array(data['B'], dtype=np.int64)

    best_perm = None
    best_cost = None
    current_perm = list(range(n))
    np.random.shuffle(current_perm)
    current_cost = compute_cost(current_perm, A, B)

    while time.time() - start_time < budget:
        improved = True
        while improved and time.time() - start_time < budget:
            improved = False
            for i in range(n):
                for j in range(i + 1, n):
                    for k in range(j + 1, n):
                        for l in range(k + 1, n):
                            if time.time() - start_time >= budget:
                                break
                            new_perm = current_perm[:]
                            new_perm[i], new_perm[j], new_perm[k], new_perm[l] = \
                                current_perm[k], current_perm[i], current_perm[l], current_perm[j]
                            new_cost = compute_cost(new_perm, A, B)
                            if best_cost is None or new_cost < best_cost:
                                best_cost = new_cost
                                best_perm = new_perm[:]
                            if new_cost < current_cost:
                                current_perm = new_perm
                                current_cost = new_cost
                                improved = True
                        if time.time() - start_time >= budget:
                            break
                    if time.time() - start_time >= budget:
                        break
                if time.time() - start_time >= budget:
                    break
            if time.time() - start_time >= budget:
                break
        if best_perm is not None:
            print('PERMUTATION: ' + ' '.join(str(x + 1) for x in best_perm))
            sys.stdout.flush()
        else:
            print('PERMUTATION: ' + ' '.join(str(x + 1) for x in current_perm))
            sys.stdout.flush()
